function scan(root){ const files = {}; function walk(dir){ for(const e of fs.readdirSync(dir,{withFileTypes:true})){ const p = path.join(dir,e.name); if(e.isSymbolicLink()){ files[path.relative(root,p).replaceAll('\\\\','/')] = {symlink:fs.readlinkSync(p)}; } else if(e.isDirectory()) { if(e.name"'!=='"'.git') walk(p); } else if(e.isFile()){ const b=fs.readFileSync(p); files[path.relative(root,p).replaceAll('\\\\','/')]={bytes:b.length,sha256:crypto.createHash('sha256').update(b).digest('hex')}; } } } walk(root); return {root:path.resolve(root),files}; }
