5	const equal = (a, b) => isDeepStrictEqual(a, b);
6	const mapping = x => x !== null && typeof x === 'object' && !Array.isArray(x);
7	export function cleanKeys(value) {
8	  if (value && typeof value === 'object') for (const [key, child] of Object.entries(value)) {
9	    if (['__proto__', 'prototype', 'constructor'].includes(key)) throw new Error(`不允许保留字段：${key}`);
10	    cleanKeys(child);
11	  }
12	}
13	// Reversible deltas keep append-only timelines from duplicating the whole past.
14	export function delta(before, after, at = []) {
15	  cleanKeys(before); cleanKeys(after);
16	  if (equal(before, after)) return [];
17	  if (Array.isArray(before) && Array.isArray(after) && after.length >= before.length && before.every((x, i) => equal(x, after[i]))) {
18	    return [{ at, append: after.slice(before.length), length: before.length }];
19	  }
20	  if (mapping(before) && mapping(after)) {
21	    return [...new Set([...Object.keys(before), ...Object.keys(after)])].flatMap(key => {
22	      if (Object.hasOwn(before, key) && Object.hasOwn(after, key)) return delta(before[key], after[key], [...at, key]);
23	      return [{ at: [...at, key], had: Object.hasOwn(before, key), has: Object.hasOwn(after, key),
24	        ...(Object.hasOwn(before, key) ? { before: before[key] } : {}), ...(Object.hasOwn(after, key) ? { after: after[key] } : {}) }];
25	    });
26	  }
27	  return [{ at, had: true, has: true, before, after }];
28	}
29	export function applyDelta(value, operations, reverse = false, copy = true) {
30	  let result = copy ? structuredClone(value) : value;
31	  cleanKeys(operations);
32	  for (const op of reverse ? [...operations].reverse() : operations) {
33	    if (!Array.isArray(op.at) || op.at.some(x => typeof x !== 'string' || ['__proto__', 'prototype', 'constructor'].includes(x))) throw new Error('差量路径损坏');
34	    let parent = result;
35	    for (const key of op.at.slice(0, -1)) {
36	      if (!mapping(parent) || !Object.hasOwn(parent, key)) throw new Error('差量父路径损坏');
37	      parent = parent[key];
38	    }
39	    const key = op.at.at(-1), current = op.at.length ? parent[key] : result;
40	    if (Object.hasOwn(op, 'append')) {
41	      const expected = reverse ? op.length + op.append.length : op.length;
42	      if (!Array.isArray(current) || current.length !== expected || (reverse && !equal(current.slice(op.length), op.append))) throw new Error('差量数组基线不一致');
43	      if (!copy) { if (reverse) current.splice(op.length); else current.push(...structuredClone(op.append)); continue; }
44	      const next = reverse ? current.slice(0, op.length) : [...current, ...op.append];
45	      if (op.at.length) parent[key] = next; else result = next;
46	    } else {
47	      const exists = reverse ? op.has : op.had, expected = reverse ? op.after : op.before;
48	      if ((op.at.length && Object.hasOwn(parent, key) !== exists) || (exists && !equal(current, expected))) throw new Error('差量对象基线不一致');
